<?php
require dirname(__DIR__).'/includes/bootstrap.php';require_permission('tasks.create');verify_csrf();$title=trim((string)($_POST['title']??''));$assignee=(int)($_POST['primary_assignee_id']??0);if($title===''||!$assignee){flash('error','Task title and assignee are required.');redirect('tasks.php');}try{transaction(function(PDO $pdo)use($title,$assignee){$code='TSK-'.date('ymdHis').'-'.random_int(10,99);$priority=in_array($_POST['priority']??'',['low','medium','high','urgent'],true)?$_POST['priority']:'medium';$due=!empty($_POST['due_at'])?date('Y-m-d H:i:s',strtotime((string)$_POST['due_at'])):null;$cat=(int)($_POST['category_id']??0)?:null;$pdo->prepare('INSERT INTO tasks(task_code,title,description,category_id,priority,created_by,primary_assignee_id,start_date,due_at,status,progress) VALUES(?,?,?,?,?,?,?,CURDATE(),?,"to_do",0)')->execute([$code,$title,trim((string)($_POST['description']??''))?:null,$cat,$priority,current_user_id(),$assignee,$due]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT IGNORE INTO task_assignees(task_id,employee_id) VALUES(?,?)')->execute([$id,$assignee]);$pdo->prepare('INSERT INTO task_activity_logs(task_id,user_id,action,to_value) VALUES(?,? ,"created","to_do")')->execute([$id,current_user_id()]);$q=$pdo->prepare('SELECT user_id FROM employees WHERE id=?');$q->execute([$assignee]);$uid=(int)$q->fetchColumn();if($uid)create_notification($uid,'task_assignment','New task assigned',$code.' — '.$title,'assignment-'.$id,url('tasks.php'));audit('task.created','task',$id,['assignee'=>$assignee]);});flash('success','Task created and assignee notified.');}catch(Throwable $e){flash('error','Could not create the task.');}redirect('tasks.php');
